// src/components/*/{meta,examples} + tokens → manifest/components.json, llms.txt, llms-full.txt, ai/ generated files
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { ATTRIBUTES, CATEGORIES, ORDER, PUBLIC_HOOKS, RULES, UTILITIES } from "./lib/contract.mjs";
import { finish, output, remove } from "./lib/output.mjs";
import { loadTokens } from "./lib/tokens.mjs";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const pkg = JSON.parse(readFileSync(join(root, "package.json"), "utf8"));
const { tokens, resolve, valueIn, themes, brands } = loadTokens(root);
const extraThemes = themes.filter((t) => t.name !== t.base);

const read = (p) => readFileSync(join(root, p), "utf8").trimEnd();

const CATEGORY_ORDER = Object.keys(CATEGORIES);
const rank = (list, x) => (list.includes(x) ? list.indexOf(x) : list.length);

const components = readdirSync(join(root, "src/components")).map((slug) => {
  const dir = `src/components/${slug}`;
  const meta = JSON.parse(read(`${dir}/${slug}.meta.json`));
  const files = {
    css: `${dir}/${slug}.css`,
    js: `${dir}/${slug}.ts`,
    react: `${dir}/${slug}.react.tsx`,
    meta: `${dir}/${slug}.meta.json`,
  };
  if (existsSync(join(root, `${dir}/${slug}.element.ts`))) files.element = `${dir}/${slug}.element.ts`;
  return {
    ...meta,
    files,
    examples: (meta.examples ?? []).map((ex) => ({
      ...ex,
      html: existsSync(join(root, `${dir}/examples/${ex.id}.html`)) ? read(`${dir}/examples/${ex.id}.html`) : null,
      react: existsSync(join(root, `${dir}/examples/${ex.id}.tsx`)) ? read(`${dir}/examples/${ex.id}.tsx`) : null,
    })),
  };
}).sort((a, b) => rank(CATEGORY_ORDER, a.category) - rank(CATEGORY_ORDER, b.category) || rank(ORDER, a.slug) - rank(ORDER, b.slug) || a.slug.localeCompare(b.slug));

/** Components grouped by category, in display order: [["Actions", [button, menu]], …]. */
const byCategory = CATEGORY_ORDER.map((cat) => [cat, components.filter((c) => c.category === cat)]).filter(([, list]) => list.length);

const manifestTokens = tokens.map((t) => {
  const entry = { name: t.name, cssVar: t.cssVar, type: t.type, value: resolve(t.value) };
  if (t.light !== undefined) entry.light = resolve(t.light);
  if (t.light !== undefined && t.css === undefined && extraThemes.length) entry.themes = Object.fromEntries(extraThemes.map((th) => [th.name, valueIn(t, th.name)]));
  if (t.category) entry.category = t.category;
  if (t.density !== undefined) entry.density = t.density;
  if (t.css !== undefined) entry.css = t.css;
  if (t.description) entry.description = t.description;
  return entry;
});

const elements = components.filter((c) => c.element).map((c) => c.element.tag);
// Framework-free controllers (connectPopover…) and what dist/elements.global.js puts on window.ayywi, read from the source.
const controllers = components
  .flatMap((c) => [...read(c.files.js).matchAll(/export function ((?:connect|enhance)\w+)/g)].map((m) => m[1]))
  .sort();
const globals = [...read("src/elements/global.ts").matchAll(/export \{([^}]*)\}/g)].flatMap((m) => m[1].split(",").map((x) => x.trim()).filter(Boolean));

const manifest = {
  $comment: "GENERATED by scripts/build-manifest.mjs — machine-readable context for AI agents and tools. Do not edit.",
  name: pkg.name,
  version: pkg.version,
  description: pkg.description,
  entrypoints: {
    "@danitesler/ayywi/css": "Full stylesheet (tokens + base + all components) in cascade layers ayywi.tokens < ayywi.base < ayywi.components < ayywi.brand — any unlayered app CSS wins. @danitesler/ayywi/ayywi.min.css is the minified file.",
    "@danitesler/ayywi/ayywi.unlayered.css": "Same without cascade layers. Use it when an unlayered CSS reset (Tailwind v3 preflight, normalize.css) would otherwise override components.",
    "@danitesler/ayywi/css/<file>.css": "Per-file layered CSS: tokens.css, base.css, then one file per component (button.css, card.css…).",
    "@danitesler/ayywi/brands/<name>.css": `Ready-made brands (${brands.map((b) => b.name).join(", ") || "none"}), applied with data-brand="<name>" or setBrand("<name>"). Make your own with \`npx ayywi brand\`.`,
    "@danitesler/ayywi/fonts.css": "Self-hosted brand fonts (Sora, Unbounded, Caveat; woff2, unicode-range subsets). @danitesler/ayywi/fonts-google.css loads them from Google instead.",
    ayywi: `Framework-free JS: tokens, class helpers (buttonClass…), controllers that wire behaviour onto your markup and return a cleanup (${controllers.join(", ")}), toast(), iconSvg(), paginationRange(), setTheme/setDensity/getColorScheme, themeInitScript, createBrand/brandCss/setBrand, cssVar(). Server-safe.`,
    "@danitesler/ayywi/react": "React components (re-exports everything from ayywi). Marked \"use client\".",
    "@danitesler/ayywi/elements": `Custom elements for any framework or plain HTML: ${elements.map((e) => `<${e}>`).join(", ")}, plus the card spotlight. dist/elements.global.js registers them from a <script> and exposes window.ayywi (${globals.join(", ")}).`,
    "@danitesler/ayywi/tokens.json": "DTCG-style token source ($value = dark, extensions hold light/density). Extra themes are defined in tokens/themes/*.json.",
    "@danitesler/ayywi/tokens/<file>": `Exports for other platforms: ${themes.map((t) => `${t.name}.json`).join(", ")}, density/*.json (plain DTCG, for Style Dictionary / Figma), brands/<name>/<theme>.json (a brand's overrides to layer over its theme), ayywi.scss, Ayywi.swift (SwiftUI), Ayywi.kt (Jetpack Compose).`,
    "@danitesler/ayywi/tailwind-preset": "Tailwind v3 preset.",
    "@danitesler/ayywi/tailwind.css": "Tailwind v4 @theme mapping.",
    "npx ayywi": "CLI: `lint` (checks app code against this manifest), `brand` (a brand stylesheet from a seed colour, contrast checked), `init` (sets up AI agent files + MCP), `mcp` (MCP server over stdio).",
  },
  conventions: {
    classPrefix: "ayy-",
    naming: "BEM: .ayy-block, .ayy-block__element, .ayy-block--modifier. Modifiers combine: class=\"ayy-button ayy-button--outline ayy-button--sm\".",
    state: "State lives in native/ARIA attributes (disabled, :checked, aria-selected, aria-invalid, [open], :popover-open) so every framework drives it the same way.",
    theming: `No attribute = follow OS (dark or light). data-theme=${themes.map((t) => `"${t.name}"`).join(" | ")} forces a theme on any element and its subtree (.dark/.light classes work too). See "themes" for what each one does; every theme keeps text at WCAG AA. setTheme() switches and persists; getColorScheme() says "dark" or "light".`,
    density: "Controls default to compact (touch on touch-first devices). data-density=\"compact\" | \"comfortable\" | \"touch\" on any element resizes buttons, inputs, tabs, switches, checkboxes and menu items below it.",
    branding: "A brand is one seed colour plus optional fonts and a shape. createBrand() (or `npx ayywi brand`, or the MCP create_brand tool) turns it into an 11-step scale (--ayy-brand-50…950, the seed itself at its nearest step) and, for dark and for light themes, a primary, primary-fg and ring taken from the scale step nearest the seed that keeps 4.5:1 text on the button and 3:1 against every surface in every theme. Fonts get ayywi's fallbacks (system fonts for body text); shape pill | round | soft | sharp (or exact radius) sets --ayy-radius-control, -card and -button. brandCss() writes it in the ayywi.brand layer for [data-brand=\"<name>\"]; setBrand(brand) adds it to the page and sets the attribute. Components never change, only tokens.",
    direction: "All layout uses logical properties; set dir=\"rtl\" on any ancestor and components mirror. Icons that point along the reading direction (arrows) need directional (ayy-icon--directional) to mirror too.",
    elements: "Custom elements are light DOM (no shadow root): write the same ayy- markup inside them; they add behaviour. Vue: compilerOptions.isCustomElement = (t) => t.startsWith(\"ayy-\"); Angular: CUSTOM_ELEMENTS_SCHEMA.",
    highContrast: "Every stateful component has a forced-colors (Windows High Contrast) style using system colours.",
    icons: "Hugeicons is the icon library: install @hugeicons/core-free-icons (an optional peer; ayywi renders its data, so there's still no runtime dependency). React: <Icon icon={Search01Icon} />. Elsewhere: iconSvg(Search01Icon), or the SVG pasted from hugeicons.com with class=\"ayy-icon\" and no fixed colour attributes. Icons use currentColor and 1.25em (the text size); size sm/md/lg/xl is 16/20/24/32px (--ayy-size-icon-*).",
  },
  rules: RULES,
  attributes: ATTRIBUTES,
  themes: themes.map((t) => ({ name: t.name, base: t.base, description: t.description })),
  categories: CATEGORIES,
  publicCustomProperties: PUBLIC_HOOKS,
  utilities: UTILITIES,
  brands: brands.map((b) => ({ name: b.name, description: b.input.description, input: b.input })),
  tokens: manifestTokens,
  components,
};

// ---- llms-full.txt ----
const fence = (lang, code) => `\`\`\`${lang}\n${code}\n\`\`\``;
const list = (items) => items.map((i) => `- ${i}`).join("\n");
const md = [];
md.push(`# ${pkg.name} ${pkg.version} — full context for LLMs`);
md.push(`> ${pkg.description}`);
md.push(
  `Generated from source by scripts/build-manifest.mjs. Structured version: manifest/components.json. Query it live with the MCP server: \`npx ayywi mcp\`.

## How to use it

- Any framework / plain HTML: load \`@danitesler/ayywi/css\` and write the class names below.
- React: \`import { Button } from "@danitesler/ayywi/react"\` plus the CSS.
- Vue, Svelte, Angular, Solid, Lit: class names or helpers (\`import { buttonClass } from "@danitesler/ayywi"\`), and \`import "@danitesler/ayywi/elements"\` for interactive components (${elements.map((e) => `<${e}>`).join(", ")}).
- Plain HTML: \`<link rel="stylesheet" href=".../dist/ayywi.min.css">\` + \`<script src=".../dist/elements.global.js" defer></script>\` (also gives window.ayywi: ${globals.join(", ")}). Add \`<link rel="stylesheet" href=".../dist/fonts.css">\` before it for ayywi's fonts (Sora, Unbounded; system fonts otherwise), and \`<script src=".../dist/theme-init.js"></script>\` in <head> so a saved theme applies before the first paint.
- One component at a time: \`llms/<slug>.md\` (llms/button.md, llms/table.md…), listed in llms.txt.
- Check your work: \`npx ayywi lint\`.`,
);
md.push(`## Rules\n\n${list(RULES)}`);
md.push(`## Conventions\n\n${list(Object.entries(manifest.conventions).map(([k, v]) => `**${k}**: ${v}`))}`);
md.push(`## Global attributes\n\n${list(Object.entries(ATTRIBUTES).map(([k, v]) => `\`${k}\`: ${v}`))}`);
md.push(
  `## Tokens\n\n| token | css var | dark (default) | light | notes |\n|---|---|---|---|---|\n${manifestTokens
    .map((t) => {
      const notes = [t.description ?? "", t.density ? `density: comfortable ${t.density.comfortable}, touch ${t.density.touch}` : ""].filter(Boolean).join(" · ");
      return `| ${t.name} | \`${t.cssVar}\` | ${Array.isArray(t.value) ? t.value.join(", ") : t.value} | ${t.light ?? ""} | ${notes.replace(/\|/g, "\\|")} |`;
    })
    .join("\n")}`,
);
md.push(
  `## Themes\n\n${list(
    themes.map((t) => {
      const overrides = t.name === t.base ? "" : ` Overrides of ${t.base}: ${t.overrides.map((o) => `\`${o.cssVar}\` ${resolve(o.value)}`).join(", ")}.`;
      return `\`${t.name}\`${t.name === t.base ? "" : ` (built on ${t.base})`} — ${t.description ?? ""}${overrides}`;
    }),
  )}`,
);
if (brands.length) {
  md.push(`## Brands\n\nShipped as \`@danitesler/ayywi/brands/<name>.css\`; make your own with \`npx ayywi brand <#seed> --name <name>\`.\n\n${list(brands.map((b) => `\`${b.name}\` — ${b.input.description ?? ""} Made from: \`${JSON.stringify(Object.fromEntries(Object.entries(b.input).filter(([k]) => k !== "description")))}\``))}`);
}
md.push(`## Public custom properties\n\n${list(Object.entries(PUBLIC_HOOKS).map(([k, v]) => `\`${k}\`: ${v}`))}`);
md.push(`## Utility classes\n\n${list(Object.entries(UTILITIES).map(([k, v]) => `\`.${k}\`: ${v}`))}`);
md.push(`## Components by category\n\n${list(byCategory.map(([cat, list]) => `**${cat}** (${CATEGORIES[cat]}): ${list.map((c) => c.name).join(", ")}`))}`);
/** A component's section: classes, states, JS, element, React, a11y, do/don't and examples. Shared by llms-full.txt and llms/<slug>.md. */
function componentMarkdown(c, h = "##") {
  const part = [`${h} ${c.name}`, `Category: ${c.category}. ${c.description}`];
  part.push(`**Classes**\n${list(Object.entries(c.classes).map(([k, v]) => `\`.${k}\` — ${v}`))}`);
  if (c.states) part.push(`**States**\n${list(Object.entries(c.states).map(([k, v]) => `\`${k}\` — ${v}`))}`);
  if (c.js) part.push(`**JS (framework-free)**: ${c.js}`);
  if (c.element) {
    part.push(
      `**Custom element** \`<${c.element.tag}>\` (@danitesler/ayywi/elements) — ${c.element.children ?? ""}\n${list([
        ...Object.entries(c.element.attributes ?? {}).map(([k, v]) => `attribute \`${k}\`: ${v}`),
        ...Object.entries(c.element.events ?? {}).map(([k, v]) => `event \`${k}\`: ${v}`),
      ])}`,
    );
  }
  part.push(
    `**React** — \`${c.react.import}\`\n${list(
      Object.entries(c.react.components).map(([name, def]) => {
        const props = def.props ? ` Props: ${Object.entries(def.props).map(([p, d]) => `\`${p}\` ${d}`).join("; ")}` : "";
        return `\`<${name}>\` renders ${def.renders}.${props}`;
      }),
    )}`,
  );
  if (c.a11y?.length) part.push(`**Accessibility**\n${list(c.a11y)}`);
  if (c.do?.length) part.push(`**Do**\n${list(c.do)}`);
  if (c.dont?.length) part.push(`**Don't**\n${list(c.dont)}`);
  for (const ex of c.examples) {
    part.push(`${h}# ${c.name} — ${ex.title}`);
    if (ex.html) part.push(`HTML (also Vue/Svelte/Angular templates, server templates):\n\n${fence("html", ex.html)}`);
    if (ex.react) part.push(`React:\n\n${fence("tsx", ex.react)}`);
  }
  return part.join("\n\n");
}
for (const c of components) md.push(componentMarkdown(c));

// ---- llms/<slug>.md: one component per file, for tools that should fetch only what they use ----
const componentPages = components.map((c) => [
  c.slug,
  `${componentMarkdown(c, "#")}

---
Part of ${pkg.name} ${pkg.version}: load \`dist/ayywi.min.css\` (and \`dist/elements.global.js\` for the <ayy-*> elements). The rules every screen follows: [llms-full.txt#rules](../llms-full.txt#rules). Every component: [llms.txt](../llms.txt).
`,
]);

// ---- llms.txt (index, llmstxt.org format) ----
const index = `# ${pkg.name}

> ${pkg.description}

Dark-first, monochrome frame with colour coming from content. Tokens are CSS custom properties prefixed --ayy-, classes are prefixed ayy-. Works in any framework; React components and custom elements render the same markup. Themes, density, brands and RTL are attributes on any element.

## Start here

- [llms-full.txt](llms-full.txt): everything in one file — rules, tokens, every component's API and examples
- [manifest/components.json](manifest/components.json): the same, as JSON
- [README.md](README.md): install and usage per framework
- [ai/AGENTS.snippet.md](ai/AGENTS.snippet.md): rules to paste into a consuming project's AGENTS.md (or run \`npx ayywi init\`)
- [ai/skills/ayywi/SKILL.md](ai/skills/ayywi/SKILL.md): how to build a page or an app with ayywi, step by step
- MCP server: \`npx ayywi mcp\` (tools: list_components, get_component, search, get_tokens, get_rules, create_brand, lint)

## Components

Each links to its own page (classes, React props, accessibility, do and don't, copy-ready HTML and React); the same sections are in llms-full.txt.

${byCategory.map(([cat, list]) => `### ${cat}\n\n${list.map((c) => `- [${c.name}](llms/${c.slug}.md): ${c.description}`).join("\n")}`).join("\n\n")}

## Optional

- [tokens/tokens.json](tokens/tokens.json): token source (DTCG-style)
- [ai/skills/ayywi/reference.md](ai/skills/ayywi/reference.md): one-screen cheat sheet of every class and React component
`;

// ---- ai/ consumer kit (generated parts) ----
const GENERATED = "<!-- GENERATED by scripts/build-manifest.mjs — edit scripts/lib/contract.mjs or component meta instead. -->";
const numbered = RULES.map((r, i) => `${i + 1}. ${r}`).join("\n");
const lookup = `Look up a component before using it — via the ayywi MCP server (\`get_component\`) if it's configured, else \`node_modules/@danitesler/ayywi/manifest/components.json\` (JSON) or \`node_modules/@danitesler/ayywi/llms-full.txt\` (markdown). Each entry lists classes, variants, React props, custom element, accessibility notes, do/don't and copy-ready examples. Run \`npx ayywi lint\` when you're done.`;

const snippet = `${GENERATED}
## UI: ayywi design system

This project's UI uses **ayywi** (\`ayywi\` on npm). ${lookup}

${numbered}

Components — ${byCategory.map(([cat, list]) => `${cat}: ${list.map((c) => c.name).join(", ")}`).join("; ")}. If something is missing, compose it from these and the tokens — don't pull in another UI kit.
`;

const cursorRule = `---
description: ayywi design system rules — use when writing or editing UI, styles, components, forms or dialogs
globs: **/*.tsx, **/*.jsx, **/*.vue, **/*.svelte, **/*.astro, **/*.html, **/*.css, **/*.scss, **/*.erb, **/*.blade.php, **/*.twig, **/*.jinja, **/*.hbs, **/*.cshtml, **/*.templ
alwaysApply: false
---
${GENERATED}
# ayywi

${lookup}

${numbered}
`;

const cheat = [
  `${GENERATED}
# ayywi component cheat sheet

CSS: \`import "@danitesler/ayywi/css"\` (or \`<link href=".../dist/ayywi.min.css">\`). React: \`import { … } from "@danitesler/ayywi/react"\`. Other frameworks: class names, helpers from \`"@danitesler/ayywi"\`, and \`import "@danitesler/ayywi/elements"\` for ${elements.map((e) => `\`<${e}>\``).join(", ")}.

Global attributes: ${Object.keys(ATTRIBUTES).map((a) => `\`${a}\``).join(", ")} (theme, density, brand, direction — on any element).

Utilities: ${Object.keys(UTILITIES).map((u) => `\`.${u}\``).join(", ")}.

Public custom properties: ${Object.keys(PUBLIC_HOOKS).map((h) => `\`${h}\``).join(", ")}.`,
  ...components.map((c) => {
    const react = Object.entries(c.react.components)
      .map(([name, def]) => `\`<${name}${def.props ? ` ${Object.keys(def.props).filter((p) => !p.startsWith("...")).join(" ")}` : ""}>\``)
      .join(", ");
    const lines = [`## ${c.name} (${c.category})`, c.description, `- Classes: ${Object.keys(c.classes).map((k) => `\`.${k}\``).join(" ")}`];
    if (c.states) lines.push(`- States: ${Object.keys(c.states).map((s) => `\`${s}\``).join(", ")}`);
    lines.push(`- React: ${react}`);
    if (c.element) lines.push(`- Element: \`<${c.element.tag}${Object.keys(c.element.attributes ?? {}).filter((a) => a !== "class").map((a) => ` ${a}`).join("")}>\`${Object.keys(c.element.events ?? {}).length ? `, events ${Object.keys(c.element.events).map((e) => `\`${e}\``).join(", ")}` : ""}`);
    if (c.js) lines.push(`- JS: ${c.js}`);
    lines.push(`- A11y: ${c.a11y.join(" ")}`);
    return lines.join("\n");
  }),
].join("\n\n");

output(join(root, "ai/AGENTS.snippet.md"), snippet);
output(join(root, "ai/cursor/ayywi.mdc"), cursorRule);
output(join(root, "ai/skills/ayywi/reference.md"), `${cheat}\n`);

output(join(root, "manifest/components.json"), `${JSON.stringify(manifest, null, 2)}\n`);
output(join(root, "llms-full.txt"), `${md.join("\n\n")}\n`);
output(join(root, "llms.txt"), index);
for (const [slug, page] of componentPages) output(join(root, "llms", `${slug}.md`), page);
// A page for a component that's gone is stale too.
for (const file of existsSync(join(root, "llms")) ? readdirSync(join(root, "llms")) : []) {
  if (!componentPages.some(([slug]) => `${slug}.md` === file)) remove(join(root, "llms", file));
}
finish("manifest");
